const user = {
  name: "Jeet",
  age: 25
};

Object.freeze(user);

user.age = 30;       // Does not change in non-strict mode
user.city = "Kolkata"; // Not added

delete user.name;    // Does not delete

console.log(user);
// { name: "Jeet", age: 25 }

const user = {
  name: "Jeet",
  age: 25
};

Object.seal(user);

user.age = 30;        // Allowed
user.city = "Kolkata"; // Not added

delete user.name;     // Not allowed

console.log(user);
// { name: "Jeet", age: 30 }

